// ตรวจความถูกต้องของคลังวิดีโอ: URL ต้องเป็นลิงก์ TikTok, กันซ้ำด้วย video id
const res = $json || {};
const list = Array.isArray(res.videos) ? res.videos : [];
const re = /tiktok\.com\/(?:@[A-Za-z0-9._-]+\/)?video\/(\d+)/i;
const seen = new Set();
const ok = [], dup = [], invalid = [];
for (const v of list) {
  const m = String(v.url || '').match(re);
  if (!m) { invalid.push(v.url || '(ไม่มี URL)'); continue; }
  const id = v.tiktokId || m[1];
  if (seen.has(id)) { dup.push(id); continue; }
  seen.add(id);
  ok.push({ id, title: v.title, status: v.status, url: v.url, viewCount: v.viewCount || 0 });
}
return [{ json: {
  total: list.length, usable: ok.length, duplicates: dup.length, invalid: invalid.length,
  sample: ok.slice(0, 5),
  message: `คลังวิดีโอ TikTok: ใช้ได้ ${ok.length}/${list.length} รายการ (ซ้ำ ${dup.length}, รูปแบบผิด ${invalid.length})`,
} }];

// รับลิงก์จากผู้ใช้/admin → ส่งต่อให้แอปตรวจ URL, กันซ้ำ และบันทึก (ไม่ scrape TikTok)
const body = ($json.body && typeof $json.body === 'object') ? $json.body : ($json || {});
const one = (v) => (v === null || v === undefined) ? '' : String(v).trim();
let urls = [];
if (Array.isArray(body.urls)) urls = body.urls.map(one).filter(Boolean);
else if (one(body.url)) urls = [one(body.url)];
urls = urls.slice(0, 200);
return [{ json: { urls, count: urls.length, valid: urls.length > 0,
  title: one(body.title) || undefined, topic: one(body.topic) || undefined,
  durationSec: Number(body.durationSec || 0) || undefined,
  hint: urls.length ? null : 'ต้องส่ง url หรือ urls (ลิงก์ TikTok)' } }];

// อ้างผลจาก node 'เพิ่ม/อัปเดตวิดีโอ' โดยตรง + ถ้าลิงก์ว่างให้ตอบ error ที่อ่านรู้เรื่อง
const asked = $('ตรวจลิงก์ที่ส่งเข้ามา').first().json;
const res = $json || {};
if (!asked.valid) return [{ json: { success: false, error: 'url_required', hint: asked.hint } }];
return [{ json: { success: res.ok === true, received: asked.count, created: res.created || 0,
  updated: res.updated || 0, failed: res.failed || 0, results: res.results || [], username: "@aka989._" } }];
